mapper.sql:
SELECT ROW_NUMBER() OVER ( ORDER BY A.REG_DTTM DESC ) AS "LINE_NO" /* Row Number */ , A.UP_CD AS "UP_CD" /* 공통코드 분류코드 */ , B.CDNM AS "UP_CDNM" /* 공통코드 분류코드명 */ , A.CD AS "CD" /* 공통코드 */ , A.CDNM AS "CDNM" /* 공통코드명 */ , A.CD_SEQNO AS "CD_SEQNO" /* 코드 순서 */ , A.USEYN AS "USEYN" /* 사용여부 */ , A.CMMN_CD_ID AS "CMMN_CD_ID" /* 공통코드 ID */ FROM TB_LMS_CMMN_CD A JOIN TB_LMS_CMMN_CD B ON A.UP_CD = B.CD AND B.UP_CD = B.CD WHERE A.ORG_ID = #{orgId}
AND A.UP_CD = A.CD AND A.USEYN = 'Y'
AND A.UP_CD != A.CD AND A.UP_CD = #{upCd}
AND A.CDNM LIKE '%' || #{cdnm} || '%'

mapper.insert:
/*	설명	:	관리자상위공통코드등록	*/

INSERT	INTO	TB_LMS_CMMN_CD
		( CMMN_CD_ID	/* 공통코드 아이디 (PK) */
		, ORG_ID		/* 기관 아이디 */
		, LANG_CD		/* 언어 코드 */
		, UP_CD			/* 상위 코드 */
		, CD			/* 코드 */
		, CDNM			/* 코드명 */
		, CD_SEQNO		/* 코드 순서 */
		, USEYN			/* 사용 여부 */
		, RGTR_ID		/* 등록자 아이디 */
		, REG_DTTM		/* 등록 일시 */ )
VALUES
		( #{cmmnCdId}
		, #{orgId}
		, #{langCd}
		, #{upCd}
		, #{upCd}
		, #{upCdnm}
		, 0
		, 'Y'
		, #{rgtrId}
		, TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') )

mapper.update:
/*	설명 : 관리자상위공통코드수정	*/
UPDATE
	TB_LMS_CMMN_CD
SET
	UP_CD		=	#{updtUpCd}
	, CD		= 	#{updtUpCd}
	, CDNM		=	#{upCdnm}
	, MDFR_ID	=	#{mdfrId}
	, MOD_DTTM	=	TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
WHERE
	CMMN_CD_ID = #{cmmnCdId}
	AND ORG_ID = #{orgId}
	AND UP_CD = CD

mapper.delete:
/*	설명 : 관리자상위공통코드삭제	*/
DELETE FROM
	TB_LMS_CMMN_CD
WHERE
	UP_CD = #{upCd}
	AND ORG_ID = #{orgId}

