mapper.update:
/*	설명 : 관리자공통코드수정 */
UPDATE
	TB_LMS_CMMN_CD
SET



		UP_CD		=	#{updtUpCd}
		, MDFR_ID	=	#{mdfrId}
		, MOD_DTTM	=	TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
	WHERE
		UP_CD = #{upCd}
		AND ORG_ID = #{orgId}
		AND UP_CD != CD



		CD			=	#{cd}
		, CDNM		=	#{cdnm}
		, CD_SEQNO	=	#{cdSeqno}
		, USEYN		=	#{useyn}
		, MDFR_ID	=	#{mdfrId}
		, MOD_DTTM	=	TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
	WHERE
		CMMN_CD_ID = #{cmmnCdId}

