mapper.select:
/*	설명 : 자식코드조회	*/
SELECT	CC.*
FROM 	TB_LMS_CMMN_CD CC
WHERE 	1 = 1
		AND	CC.UP_CD = #{upCd}
		AND CC.USEYN = 'Y'	AND		CC.CD_SEQNO != 0
